+			await entry.loading;
+			return entry;
+		}
+		const fingerprint = fingerprintOf(entry.pluginPath);
+		const upToDate =
+			!options.force &&
+			entry.fingerprint === fingerprint &&
+			entry.state !== "disabled" &&
+			entry.state !== "loading";
